create table wksp_dtesc.sgt_evento_operativo (
    id                       number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    codigo                   varchar2(30 byte) not null enable,
    ot_id                    number,
    tipo_activo_principal_id number not null enable,
    activo_principal_id      number not null enable,
    tipo_caso                varchar2(50 byte) not null enable,
    criticidad               varchar2(20 byte) default 'MEDIA' not null enable,
    estado                   varchar2(20 byte) default 'ABIERTO' not null enable,
    titulo                   varchar2(255 byte) not null enable,
    descripcion              varchar2(2000 byte),
    reportado_por            varchar2(255 byte) not null enable,
    asignado_a               varchar2(255 byte),
    fecha_inicio_real        timestamp(6) default systimestamp not null enable,
    fecha_fin_real           timestamp(6),
    observaciones_cierre     varchar2(2000 byte),
    creado_por               varchar2(255 byte),
    creado_el                timestamp(6) default systimestamp,
    actualizado_por          varchar2(255 byte),
    actualizado_el           timestamp(6)
);

alter table wksp_dtesc.sgt_evento_operativo
    add constraint chk_sgt_evento_operativo_crit
        check ( criticidad in ( 'BAJA', 'MEDIA', 'ALTA', 'CRITICA' ) ) enable;

alter table wksp_dtesc.sgt_evento_operativo
    add constraint chk_sgt_evento_operativo_estado
        check ( estado in ( 'ABIERTO', 'EN_EJECUCION', 'EN_REVISION', 'CERRADO', 'CANCELADO' ) ) enable;

alter table wksp_dtesc.sgt_evento_operativo
    add constraint pk_sgt_evento_operativo primary key ( id )
        using index enable;

alter table wksp_dtesc.sgt_evento_operativo add constraint uq_sgt_evento_operativo_codigo unique ( codigo )
    using index enable;


